import os,sys,platform,pathlib,hashlib,json,subprocess,re,datetime,sqlite3,_sqlite3
def filepin(path):
    p=pathlib.Path(path).resolve(strict=True)
    h=hashlib.sha256()
    with p.open("rb") as f:
        for data in iter(lambda:f.read(1048576),b""): h.update(data)
    st=p.stat()
    return {"path":str(p),"bytes":st.st_size,"mode":oct(st.st_mode&0o777),"mtime_ns":str(st.st_mtime_ns),"sha256":h.hexdigest()}
vm=subprocess.run(["/usr/bin/vm_stat"],capture_output=True,text=True,timeout=10,check=True)
page=int(re.search(r"page size of (\d+) bytes",vm.stdout).group(1))
counts={}
for line in vm.stdout.splitlines()[1:]:
    if ":" in line:
        name,value=line.split(":",1)
        if name in ("Pages free","Pages inactive","Pages speculative"):
            counts[name]=int(value.strip().rstrip("."))
conservative=page*sum(counts.values())
vfs=os.statvfs("/Users/me")
extension=filepin(_sqlite3.__file__)
linked=subprocess.run(["/usr/bin/otool","-L",extension["path"]],capture_output=True,text=True,timeout=10)
dependencies=[]
for line in linked.stdout.splitlines()[1:]:
    candidate=line.strip().split(" (",1)[0]
    if candidate.startswith("/") and pathlib.Path(candidate).is_file():
        dependencies.append(filepin(candidate))
framework=pathlib.Path("/Library/Frameworks/Python.framework/Versions/3.13/Python")
out={"schema":"recallweave-sql-null-membership-mac-readonly-runtime-v1","time_utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"purpose":"Read-only existing interpreter/SQLite identity and fresh guard only; no database connection, lesson SQL, parser, source write, app or browser call.","pid":os.getpid(),"uid":os.getuid(),"platform":platform.platform(),"machine":platform.machine(),"python_version":platform.python_version(),"sqlite_version":sqlite3.sqlite_version,"runtime":filepin(sys.executable),"framework":filepin(framework),"sqlite_extension":extension,"sqlite_python_init":filepin(sqlite3.__file__),"linked_libraries":dependencies,"otool":{"exit_code":linked.returncode,"stdout":linked.stdout,"stderr":linked.stderr},"guard":{"free_disk_bytes":vfs.f_bavail*vfs.f_frsize,"page_size":page,"counters":counts,"conservative_memory_bytes":conservative,"minimum_disk_bytes":268435456,"minimum_memory_bytes":2147483648,"admitted":vfs.f_bavail*vfs.f_frsize>=268435456 and conservative>=2147483648},"native_query_count":0,"new_physical_files":0}
print(json.dumps(out,ensure_ascii=False,indent=2))

