import os,sys,pathlib,hashlib,json,subprocess
node_value=os.environ.get("CODEX_PRIMARY_RUNTIME_NODE")
node=pathlib.Path(node_value).resolve(strict=True) if node_value else None
mem={}
for line in pathlib.Path("/proc/meminfo").read_text().splitlines():
    if line.startswith("MemAvailable:"): mem["mem_available_bytes"]=int(line.split()[1])*1024
for name in ("memory.max","memory.current"):
    p=pathlib.Path("/sys/fs/cgroup")/name
    mem[name]=p.read_text().strip() if p.is_file() else None
vfs=os.statvfs("/dev")
out={"purpose":"read-only existing runtime and resource identity; no new lesson SQL, parser, source or browser execution","python":str(pathlib.Path(sys.executable).resolve()),"node_configured":node_value,"node":None,"resources":{"dev_free_bytes":vfs.f_bavail*vfs.f_frsize,**mem}}
if node:
    stat=node.stat()
    out["node"]={"resolved":str(node),"bytes":stat.st_size,"mode":oct(stat.st_mode&0o777),"sha256":hashlib.sha256(node.read_bytes()).hexdigest()}
    process=subprocess.run([str(node),"--version"],capture_output=True,text=True,timeout=10)
    out["node"]["version"]={"exit_code":process.returncode,"stdout":process.stdout,"stderr":process.stderr}
print(json.dumps(out,indent=2))

